/**
 * Timestamp helpers: ISO round-tripping, relative formatting, due-date and
 * digest-window arithmetic.
 *
 * Every timestamp in Taskflow is an `IsoTimestamp` (a UTC ISO-8601 string in
 * a SQLite text column). Nothing outside this module constructs a `Date` from
 * a stored value — going through `parseIso()` keeps the "what if it is
 * malformed" answer in one place.
 *
 * Calendar days are taken on a workspace's own clock: every function that
 * decides a day boundary takes the IANA `timeZone` of that workspace.
 */
import type { IsoTimestamp } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

const MINUTE_MS = 60_000;
const HOUR_MS = 60 * MINUTE_MS;
const DAY_MS = 24 * HOUR_MS;
const WEEK_MS = 7 * DAY_MS;

export function now(): IsoTimestamp {
  return toIsoTimestamp(new Date());
}

/** Parses a stored timestamp; throws rather than yielding an Invalid Date. */
export function parseIso(value: IsoTimestamp): Date {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Malformed IsoTimestamp: "${value}"`);
  }
  return date;
}

function plural(count: number, unit: string): string {
  return `${count} ${unit}${count === 1 ? "" : "s"}`;
}

/** True when `Intl` recognises the zone name (e.g. "Asia/Tokyo"). */
export function isValidTimeZone(timeZone: string): boolean {
  try {
    zonedFormatter(timeZone);
    return true;
  } catch {
    return false;
  }
}

/**
 * "just now" / "5 minutes ago" / "in 2 days" — the wording the activity feed,
 * issue cards and comment headers all use.
 */
export function formatRelative(
  value: IsoTimestamp,
  reference: Date = new Date(),
): string {
  const deltaMs = parseIso(value).getTime() - reference.getTime();
  const past = deltaMs < 0;
  const abs = Math.abs(deltaMs);

  const phrase = ((): string => {
    if (abs < MINUTE_MS) return "just now";
    if (abs < HOUR_MS) return plural(Math.floor(abs / MINUTE_MS), "minute");
    if (abs < DAY_MS) return plural(Math.floor(abs / HOUR_MS), "hour");
    if (abs < WEEK_MS) return plural(Math.floor(abs / DAY_MS), "day");
    if (abs < 30 * DAY_MS) return plural(Math.floor(abs / WEEK_MS), "week");
    if (abs < 365 * DAY_MS) return plural(Math.floor(abs / (30 * DAY_MS)), "month");
    return plural(Math.floor(abs / (365 * DAY_MS)), "year");
  })();

  if (phrase === "just now") return phrase;
  return past ? `${phrase} ago` : `in ${phrase}`;
}

/** Absolute calendar rendering, e.g. "12 Mar 2026", in the given timezone. */
export function formatDate(value: IsoTimestamp, timezone = "UTC"): string {
  return new Intl.DateTimeFormat("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    timeZone: timezone,
  }).format(parseIso(value));
}

// ---------------------------------------------------------------------------
// Workspace-clock arithmetic
// ---------------------------------------------------------------------------

interface ZonedParts {
  readonly year: number;
  readonly month: number;
  readonly day: number;
  readonly hour: number;
  readonly minute: number;
  readonly second: number;
}

const formatters = new Map<string, Intl.DateTimeFormat>();

/** Throws a `RangeError` for a zone name `Intl` does not recognise. */
function zonedFormatter(timeZone: string): Intl.DateTimeFormat {
  const cached = formatters.get(timeZone);
  if (cached) return cached;

  const formatter = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "numeric",
    day: "numeric",
    hour: "numeric",
    minute: "numeric",
    second: "numeric",
  });
  formatters.set(timeZone, formatter);
  return formatter;
}

/** The wall-clock fields of `instant` as seen on the zone's clock. */
function zonedParts(instant: Date, timeZone: string): ZonedParts {
  const fields = new Map(
    zonedFormatter(timeZone)
      .formatToParts(instant)
      .map((part) => [part.type, Number(part.value)]),
  );
  return {
    year: fields.get("year") ?? 0,
    month: fields.get("month") ?? 1,
    day: fields.get("day") ?? 1,
    hour: fields.get("hour") ?? 0,
    minute: fields.get("minute") ?? 0,
    second: fields.get("second") ?? 0,
  };
}

/** The wall clock of `instant` read as if it were UTC, in epoch ms. */
function wallClockMs(instant: Date, timeZone: string): number {
  const p = zonedParts(instant, timeZone);
  return Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second);
}

/**
 * The real instant at which the zone's wall clock shows `wallMs` (a UTC-encoded
 * wall-clock value). Two passes settle the offset across DST transitions.
 */
function instantOfWallClock(wallMs: number, timeZone: string): Date {
  const offsetAt = (epochMs: number): number =>
    wallClockMs(new Date(epochMs), timeZone) - Math.floor(epochMs / 1000) * 1000;

  const first = wallMs - offsetAt(wallMs);
  return new Date(wallMs - offsetAt(first));
}

function dayKey(instant: Date, timeZone: string): string {
  const p = zonedParts(instant, timeZone);
  const year = String(p.year).padStart(4, "0");
  const month = String(p.month).padStart(2, "0");
  const day = String(p.day).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

/** The `YYYY-MM-DD` calendar date of `value` on the zone's clock. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  return dayKey(parseIso(value), timeZone);
}

/** The hour (0-23) that `instant` shows on the zone's clock. */
export function localHour(instant: Date, timeZone: string): number {
  return zonedParts(instant, timeZone).hour;
}

/**
 * The instant at which the zone's calendar day `days` after `reference`'s
 * calendar day began (negative values count backwards).
 */
export function shiftLocalDays(
  reference: Date,
  days: number,
  timeZone: string,
): IsoTimestamp {
  const p = zonedParts(reference, timeZone);
  const midnight = Date.UTC(p.year, p.month - 1, p.day + days);
  return toIsoTimestamp(instantOfWallClock(midnight, timeZone));
}

/** The instant at which the zone's calendar day containing `reference` began. */
export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  return shiftLocalDays(reference, 0, timeZone);
}

/** True when a due date exists and its calendar day has already ended. */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  return localDate(dueAt, timeZone) < dayKey(reference, timeZone);
}

export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/**
 * The window a digest covers, ending at the most recent `hour:00` on the
 * zone's clock at or before `reference`, and starting at the same local hour
 * on the previous calendar day. Across a DST change it spans 23 or 25 hours.
 */
export function digestWindow(
  digestHour: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHour) || digestHour < 0 || digestHour > 23) {
    throw new RangeError(`digestHour must be 0-23, got ${digestHour}`);
  }

  const today = zonedParts(reference, timeZone);
  let end = instantOfWallClock(
    Date.UTC(today.year, today.month - 1, today.day, digestHour),
    timeZone,
  );
  if (end.getTime() > reference.getTime()) {
    end = instantOfWallClock(
      Date.UTC(today.year, today.month - 1, today.day - 1, digestHour),
      timeZone,
    );
  }

  const endDay = zonedParts(end, timeZone);
  const start = instantOfWallClock(
    Date.UTC(endDay.year, endDay.month - 1, endDay.day - 1, digestHour),
    timeZone,
  );

  return {
    start: toIsoTimestamp(start),
    end: toIsoTimestamp(end),
  };
}

