/** Relative formatting, overdue detection and the digest window. */
import { describe, expect, it } from "vitest";
import {
  addDays,
  digestWindow,
  formatDate,
  formatRelative,
  isOverdue,
  now,
  parseIso,
} from "@/lib/date";
import type { IsoTimestamp } from "@/types/common";

const REFERENCE = new Date("2026-03-15T12:00:00.000Z");
const iso = (value: string): IsoTimestamp => value as IsoTimestamp;

describe("lib/date", () => {
  it("round-trips now() through parseIso()", () => {
    const stamp = now();
    expect(parseIso(stamp).toISOString()).toBe(stamp);
  });

  it("throws on a malformed timestamp rather than yielding Invalid Date", () => {
    expect(() => parseIso(iso("not-a-date"))).toThrow(RangeError);
  });

  it("formats past distances with an 'ago' suffix", () => {
    expect(formatRelative(iso("2026-03-15T11:59:30.000Z"), REFERENCE)).toBe("just now");
    expect(formatRelative(iso("2026-03-15T11:55:00.000Z"), REFERENCE)).toBe("5 minutes ago");
    expect(formatRelative(iso("2026-03-15T11:00:00.000Z"), REFERENCE)).toBe("1 hour ago");
    expect(formatRelative(iso("2026-03-13T12:00:00.000Z"), REFERENCE)).toBe("2 days ago");
    expect(formatRelative(iso("2026-03-01T12:00:00.000Z"), REFERENCE)).toBe("2 weeks ago");
  });

  it("formats future distances with an 'in' prefix", () => {
    expect(formatRelative(iso("2026-03-15T12:30:00.000Z"), REFERENCE)).toBe("in 30 minutes");
    expect(formatRelative(iso("2026-03-18T12:00:00.000Z"), REFERENCE)).toBe("in 3 days");
  });

  it("renders an absolute date in the requested timezone", () => {
    expect(formatDate(iso("2026-03-15T23:30:00.000Z"))).toBe("15 Mar 2026");
    expect(formatDate(iso("2026-03-15T23:30:00.000Z"), "Asia/Tokyo")).toBe("16 Mar 2026");
  });

  it("treats a null due date as never overdue", () => {
    expect(isOverdue(null, REFERENCE)).toBe(false);
    expect(isOverdue(iso("2026-03-15T11:59:59.000Z"), REFERENCE)).toBe(true);
    expect(isOverdue(iso("2026-03-15T12:00:01.000Z"), REFERENCE)).toBe(false);
  });

  it("adds and subtracts whole days", () => {
    expect(addDays(iso("2026-03-15T12:00:00.000Z"), 3)).toBe("2026-03-18T12:00:00.000Z");
    expect(addDays(iso("2026-03-01T12:00:00.000Z"), -1)).toBe("2026-02-28T12:00:00.000Z");
  });

  it("ends the digest window at today's digest hour once it has passed", () => {
    const window = digestWindow(8, REFERENCE);
    expect(window.end).toBe("2026-03-15T08:00:00.000Z");
    expect(window.start).toBe("2026-03-14T08:00:00.000Z");
  });

  it("falls back to yesterday's window when the digest hour has not arrived", () => {
    const window = digestWindow(20, REFERENCE);
    expect(window.end).toBe("2026-03-14T20:00:00.000Z");
    expect(window.start).toBe("2026-03-13T20:00:00.000Z");
  });

  it("rejects a digest hour outside 0-23", () => {
    expect(() => digestWindow(24, REFERENCE)).toThrow(RangeError);
    expect(() => digestWindow(-1, REFERENCE)).toThrow(RangeError);
  });
});

/**
 * Deterministic factories for actors, orgs, projects, issues and comments
 * used across the suite.
 *
 * Every factory seeds from the same `idFactory`, so a test that does not care
 * about ids gets stable ones, and a test that does can override them. All
 * default rows live in `ORG_A` — cross-tenant tests pass `orgId: ORG_B`.
 */
import { idFactory } from "@/lib/id";
import type { LimitCheck } from "@/types/billing";
import type { Comment } from "@/types/comment";
import type {
  CommentId,
  IsoTimestamp,
  IssueId,
  MemberId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Issue } from "@/types/issue";
import type { Actor, MemberWithUser, User } from "@/types/member";
import type { Organization } from "@/types/organization";
import type { Project } from "@/types/project";

const nextId = idFactory(42);

/** The default tenant every factory row belongs to. */
export const ORG_A = "01HZZZAAAAAAAAAAAAAAAAAAAA" as OrgId;
/** A second tenant, for cross-tenant assertions. */
export const ORG_B = "01HZZZBBBBBBBBBBBBBBBBBBBB" as OrgId;

export const ALICE = "01HZZZAAAAAAAAAAAAAAAAAAA1" as UserId;
export const BOB = "01HZZZBBBBBBBBBBBBBBBBBBB2" as UserId;

const EPOCH = "2026-03-01T09:00:00.000Z" as IsoTimestamp;

export function makeActor(overrides: Partial<Actor> = {}): Actor {
  return { userId: ALICE, orgId: ORG_A, role: "member", ...overrides };
}

export function makeUser(overrides: Partial<User> = {}): User {
  return {
    id: ALICE,
    email: "alice@example.com",
    name: "Alice Alvarez",
    avatarUrl: null,
    timezone: "UTC",
    emailVerifiedAt: EPOCH,
    createdAt: EPOCH,
    updatedAt: EPOCH,
    ...overrides,
  };
}

export function makeOrganization(
  overrides: Partial<Organization> = {},
): Organization {
  return {
    id: ORG_A,
    name: "Acme",
    slug: "acme",
    ownerId: ALICE,
    plan: "free",
    logoUrl: null,
    trialEndsAt: null,
    archivedAt: null,
    createdAt: EPOCH,
    updatedAt: EPOCH,
    settings: {
      defaultIssueStatus: "backlog",
      allowPublicProjects: false,
      requireTwoFactor: false,
      digestHourUtc: 8,
      enabledFlagOverrides: [],
    },
    ...overrides,
  };
}

export function makeProject(overrides: Partial<Project> = {}): Project {
  return {
    id: nextId() as ProjectId,
    orgId: ORG_A,
    name: "Website relaunch",
    slug: "website-relaunch",
    key: "WEB",
    description: null,
    visibility: "org",
    status: "active",
    leadId: ALICE,
    color: "#6366f1",
    startsAt: null,
    targetDate: null,
    archivedAt: null,
    createdAt: EPOCH,
    updatedAt: EPOCH,
    ...overrides,
  };
}

export function makeIssue(overrides: Partial<Issue> = {}): Issue {
  return {
    id: nextId() as IssueId,
    orgId: ORG_A,
    projectId: "01HZZZPPPPPPPPPPPPPPPPPPPP" as ProjectId,
    number: 1,
    title: "Fix the broken sign-up link",
    description: null,
    status: "todo",
    priority: "medium",
    authorId: ALICE,
    assigneeId: null,
    parentId: null,
    estimate: null,
    dueAt: null,
    startedAt: null,
    completedAt: null,
    labelIds: [],
    archivedAt: null,
    createdAt: EPOCH,
    updatedAt: EPOCH,
    ...overrides,
  };
}

export function makeComment(overrides: Partial<Comment> = {}): Comment {
  return {
    id: nextId() as CommentId,
    orgId: ORG_A,
    issueId: "01HZZZSSSSSSSSSSSSSSSSSSSS" as IssueId,
    authorId: ALICE,
    body: "Looking at this now.",
    parentId: null,
    editedAt: null,
    mentionedUserIds: [],
    archivedAt: null,
    createdAt: EPOCH,
    updatedAt: EPOCH,
    ...overrides,
  };
}

export function makeMember(
  overrides: Partial<MemberWithUser> = {},
): MemberWithUser {
  const user = overrides.user ?? makeUser();
  return {
    id: nextId() as MemberId,
    orgId: ORG_A,
    userId: user.id,
    role: "member",
    status: "active",
    invitedBy: null,
    joinedAt: EPOCH,
    lastSeenAt: EPOCH,
    archivedAt: null,
    createdAt: EPOCH,
    updatedAt: EPOCH,
    ...overrides,
    user,
  };
}

export function makeLimitCheck(overrides: Partial<LimitCheck> = {}): LimitCheck {
  const limit = overrides.limit ?? 3;
  const used = overrides.used ?? 1;
  return {
    resource: "seats",
    plan: "free",
    limit,
    used,
    remaining: Math.max(0, limit - used),
    exceeded: used >= limit,
    ...overrides,
  };
}

import { describe, expect, it } from "vitest";
import { buildCommandGroups } from "@/hooks/command-groups";
import { snapshotFlags } from "@/lib/feature-flags";
import { toIsoTimestamp } from "@/types/common";
import type { OrgId, UserId } from "@/types/common";
import type { PlanId } from "@/types/billing";
import type { Actor, Role } from "@/types/member";
import type { Organization } from "@/types/organization";

const ORG_ID = "org_1" as OrgId;

function org(plan: PlanId): Organization {
  const at = toIsoTimestamp("2026-01-01T00:00:00.000Z");
  return {
    id: ORG_ID,
    name: "Acme",
    slug: "acme",
    ownerId: "usr_owner" as UserId,
    plan,
    logoUrl: null,
    trialEndsAt: null,
    archivedAt: null,
    createdAt: at,
    updatedAt: at,
    settings: {
      defaultIssueStatus: "backlog",
      allowPublicProjects: false,
      requireTwoFactor: false,
      digestHourUtc: 8,
      enabledFlagOverrides: [],
    },
  };
}

function actor(role: Role): Actor {
  return { userId: "usr_1" as UserId, orgId: ORG_ID, role };
}

function idsFor(plan: PlanId, role: Role): readonly string[] {
  const organization = org(plan);
  const principal = actor(role);
  const flags = snapshotFlags({
    orgId: ORG_ID,
    userId: principal.userId,
    plan,
    role,
  });
  return buildCommandGroups(organization, principal, flags).flatMap((group) =>
    group.items.map((item) => item.id),
  );
}

describe("command-groups", () => {
  it("offers creation commands to a member", () => {
    const ids = idsFor("growth", "member");
    expect(ids).toContain("create:issue");
    expect(ids).toContain("create:project");
  });

  it("withholds invite and billing from a member", () => {
    const ids = idsFor("growth", "member");
    expect(ids).not.toContain("create:invite");
    expect(ids).not.toContain("nav:billing");
  });

  it("gives billing to the owner only", () => {
    expect(idsFor("growth", "owner")).toContain("nav:billing");
    expect(idsFor("growth", "admin")).not.toContain("nav:billing");
  });

  it("hides the board until the plan includes the kanban flag", () => {
    expect(idsFor("free", "admin")).not.toContain("nav:board");
    expect(idsFor("starter", "admin")).toContain("nav:board");
  });

  it("hides the activity feed below the growth plan", () => {
    expect(idsFor("starter", "admin")).not.toContain("nav:activity");
    expect(idsFor("growth", "admin")).toContain("nav:activity");
  });

  it("requires both the CSV flag and activity:export for the audit export", () => {
    // starter has csv_export but a member lacks activity:export
    expect(idsFor("starter", "member")).not.toContain("export:activity");
    expect(idsFor("starter", "admin")).toContain("export:activity");
    // free has no csv_export at all
    expect(idsFor("free", "owner")).not.toContain("export:activity");
  });

  it("gives a viewer navigation but no creation commands", () => {
    const ids = idsFor("enterprise", "viewer");
    expect(ids).toContain("nav:issues");
    expect(ids).not.toContain("create:issue");
  });

  it("groups items under their headings", () => {
    const groups = buildCommandGroups(
      org("enterprise"),
      actor("owner"),
      snapshotFlags({
        orgId: ORG_ID,
        userId: "usr_1" as UserId,
        plan: "enterprise",
        role: "owner",
      }),
    );
    expect(groups.map((group) => group.heading)).toEqual([
      "Create",
      "Go to",
      "Export",
    ]);
  });
});

/**
 * In-memory SQLite fixture: migrate, seed a tenant pair, reset between tests.
 *
 * Repository and service suites call `setupTestDb()` once, `resetTestDb()` in
 * `beforeEach` and `seedTwoTenants()` when they need two organizations to
 * prove a query is org-scoped. The database is `:memory:`, so nothing here
 * touches the developer's `data/taskflow.db`.
 */
// Aliased on import: the contract calls it `useInMemoryDb`, which the
// react-hooks lint rule would otherwise mistake for a React hook here.
import { getDb, useInMemoryDb as attachInMemoryDb } from "@/server/db";
import { runMigrations } from "@/server/db/migrate";
import { organizations } from "@/server/db/schema/organizations";
import { users } from "@/server/db/schema/users";
import type { Organization } from "@/types/organization";
import { makeOrganization, ORG_A, ORG_B } from "./factories";

let migrated = false;

/** Points the singleton client at an in-memory database and migrates it. */
export async function setupTestDb(): Promise<void> {
  attachInMemoryDb();
  await runMigrations(":memory:");
  migrated = true;
}

/** Truncates every table, keeping the schema — cheaper than re-migrating. */
export async function resetTestDb(): Promise<void> {
  if (!migrated) await setupTestDb();

  const db = getDb();
  const tables = db.$client
    .prepare(
      "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE '__drizzle%'",
    )
    .all() as readonly { name: string }[];

  db.$client.pragma("foreign_keys = OFF");
  for (const table of tables) {
    db.$client.prepare(`DELETE FROM "${table.name}"`).run();
  }
  db.$client.pragma("foreign_keys = ON");
}

/**
 * Inserts two organizations owned by two different users. Every "does this
 * query filter by orgId?" test seeds through here so the negative case is a
 * real row in a real other tenant, not an absence.
 */
export async function seedTwoTenants(): Promise<{
  orgA: Organization;
  orgB: Organization;
}> {
  const db = getDb();

  const orgA = makeOrganization({ id: ORG_A, name: "Acme", slug: "acme" });
  const orgB = makeOrganization({
    id: ORG_B,
    name: "Globex",
    slug: "globex",
    ownerId: orgA.ownerId,
  });

  await db
    .insert(users)
    .values({
      id: orgA.ownerId,
      email: "owner@example.com",
      name: "Test Owner",
      passwordHash: "scrypt:00:00",
      timezone: "UTC",
      createdAt: orgA.createdAt,
      updatedAt: orgA.updatedAt,
    })
    .onConflictDoNothing();

  for (const org of [orgA, orgB]) {
    await db.insert(organizations).values({
      id: org.id,
      name: org.name,
      slug: org.slug,
      ownerId: org.ownerId,
      plan: org.plan,
      logoUrl: org.logoUrl,
      trialEndsAt: org.trialEndsAt,
      // `OrganizationSettings` is flattened across columns on this table.
      defaultIssueStatus: org.settings.defaultIssueStatus,
      allowPublicProjects: org.settings.allowPublicProjects,
      requireTwoFactor: org.settings.requireTwoFactor,
      digestHourUtc: org.settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(org.settings.enabledFlagOverrides),
      archivedAt: org.archivedAt,
      createdAt: org.createdAt,
      updatedAt: org.updatedAt,
    });
  }

  return { orgA, orgB };
}

